// Grade on bounce and reply. Deliberately NOT on open rate: Apple Mail Privacy
// Protection pre-fetches images, so a chunk of 'opens' are a proxy server, not a human.
// Anyone still optimising open rate is optimising noise, and saying so is usually the
// moment a client realises we have done this before.
const a = $('[cred] Smartlead - campaign analytics').first().json || {};
const accountsRes = $input.first().json;
const accounts = Array.isArray(accountsRes) ? accountsRes : (accountsRes && accountsRes.data) || [];

const num = (v) => Number(v || 0);
const sent = num(a.sent_count || a.sent);
const bounced = num(a.bounce_count || a.bounced);
const replied = num(a.reply_count || a.replied);
const unsubscribed = num(a.unsubscribed_count || a.unsubscribed);
const opened = num(a.open_count || a.opened);

const rate = (n) => (sent > 0 ? Math.round((n / sent) * 1000) / 10 : 0);

const bounceRate = rate(bounced);
const replyRate = rate(replied);
const unsubRate = rate(unsubscribed);

const BOUNCE_WARN = Number($env.BOUNCE_WARN_PCT || 3);
const BOUNCE_STOP = Number($env.BOUNCE_STOP_PCT || 5);
const REPLY_FLOOR = Number($env.REPLY_FLOOR_PCT || 1);
const UNSUB_WARN = Number($env.UNSUB_WARN_PCT || 1);
const MIN_SAMPLE = Number($env.MIN_SAMPLE || 100);

const reasons = [];
let verdict = 'healthy';

// Below the sample floor, every rate is noise. Say 'too early' rather than guessing.
if (sent < MIN_SAMPLE) {
  verdict = 'too_early';
  reasons.push('only ' + sent + ' sent - below the ' + MIN_SAMPLE + ' sample floor, rates are not meaningful yet');
} else {
  if (bounceRate >= BOUNCE_STOP) { verdict = 'stop'; reasons.push('bounce ' + bounceRate + '% at or above the ' + BOUNCE_STOP + '% stop line'); }
  else if (bounceRate >= BOUNCE_WARN) { verdict = 'warn'; reasons.push('bounce ' + bounceRate + '% above the ' + BOUNCE_WARN + '% warning line'); }

  if (unsubRate >= UNSUB_WARN) { if (verdict !== 'stop') verdict = 'warn'; reasons.push('unsubscribe ' + unsubRate + '% - the copy or the targeting is off'); }
  if (replyRate < REPLY_FLOOR) { if (verdict === 'healthy') verdict = 'warn'; reasons.push('reply ' + replyRate + '% below the ' + REPLY_FLOOR + '% floor'); }
}

// Per-inbox view. One bad mailbox drags a whole campaign down and is invisible in the
// campaign average.
const inboxes = accounts.map((acc) => {
  const s = num(acc.sent_count);
  const b = num(acc.bounce_count);
  const r = s > 0 ? Math.round((b / s) * 1000) / 10 : 0;
  return {
    email: acc.from_email || acc.email || 'unknown',
    sent: s,
    bounce_pct: r,
    warmup: acc.warmup_details ? (acc.warmup_details.status || '') : '',
    hot: r >= BOUNCE_STOP && s >= 20
  };
});

const badInboxes = inboxes.filter((i) => i.hot);
if (badInboxes.length) {
  if (verdict !== 'stop') verdict = 'warn';
  reasons.push(badInboxes.length + ' mailbox(es) bouncing at or above ' + BOUNCE_STOP + '%');
}

return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  verdict: verdict,
  should_pause: verdict === 'stop',
  reasons: reasons,
  sent: sent,
  bounce_pct: bounceRate,
  reply_pct: replyRate,
  unsub_pct: unsubRate,
  open_pct_unreliable: rate(opened),
  inboxes: inboxes,
  bad_inboxes: badInboxes
}}];

// Report the two numbers that decide whether to keep sending, and name the mailboxes.
const g = $('grade the campaign').first().json;

const icon = { healthy: ':white_check_mark:', warn: ':warning:', stop: ':octagonal_sign:', too_early: ':hourglass:' }[g.verdict] || ':grey_question:';
const lines = [icon + ' *Deliverability ' + g.date + '* - ' + g.verdict.toUpperCase().split('_').join(' ')];

lines.push('Sent ' + g.sent + '  |  bounce *' + g.bounce_pct + '%*  |  reply *' + g.reply_pct + '%*  |  unsub ' + g.unsub_pct + '%');

if (g.reasons.length) {
  lines.push('');
  g.reasons.forEach((r) => lines.push('  - ' + r));
}

if (g.bad_inboxes.length) {
  lines.push('');
  lines.push('*Mailboxes to pull out:*');
  g.bad_inboxes.forEach((i) => lines.push('  - ' + i.email + ' - ' + i.bounce_pct + '% over ' + i.sent + ' sends'));
}

if (g.should_pause && String($env.AUTO_PAUSE || 'true') === 'true') {
  lines.push('');
  lines.push(':octagonal_sign: *Campaign paused automatically.* Fix the list before restarting - sending through a bounce problem is how the domain goes.');
}

lines.push('');
lines.push('_Open rate (' + g.open_pct_unreliable + '%) is logged but not graded - Apple Mail Privacy Protection pre-fetches images, so a share of those opens are a proxy, not a person._');

return [{ json: { text: lines.join('\n') } }];
